package fr.jmproduction.pocketdoor.data;
import java.util.*; import net.minecraft.nbt.*; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData;
public class PocketDoorSavedData extends SavedData {private final Set<UUID> finished=new HashSet<>(); public static PocketDoorSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(PocketDoorSavedData::load,PocketDoorSavedData::new,"pocketdoor_dialogue");} public static PocketDoorSavedData load(CompoundTag t){PocketDoorSavedData d=new PocketDoorSavedData();ListTag x=t.getList("finished",8);for(int i=0;i<x.size();i++)try{d.finished.add(UUID.fromString(x.getString(i)));}catch(IllegalArgumentException ignored){}return d;} public boolean isFinished(UUID u){return finished.contains(u);} public void markFinished(UUID u){if(finished.add(u))setDirty();} @Override public CompoundTag save(CompoundTag t){ListTag x=new ListTag();finished.forEach(u->x.add(StringTag.valueOf(u.toString())));t.put("finished",x);return t;}}
